const $=s=>document.querySelector(s),form=$('#generator-form');let importedCircuit=new URLSearchParams(window.location.search).has('ap')?{state:projectContext?.electronics||null,notice:projectImport.notice}:readCircuitState(window.location.search),kitContext=null,circuit,selection=null,filter='all',step=0,guide=null;let mode=normalisePresentation(new URLSearchParams(location.search).get('view')),inspection=null,unavailableReason='';const completed=new Set();let profiles={neck:'generic',bridge:'generic'};
