 $('#presentation-description').textContent={build:'Where each wire gets soldered. All physical connections remain visible; choose a part or connection for its destinations.',trace:'Follow exact conductors, terminals and closed selector contacts. Filters change emphasis, not connectivity.',explain:'Choose a component or terminal to learn its role and current connections. Explore the guided circuit walkthrough below.'}[mode];
