function paint(){if(!circuit)return;const active=document.activeElement,focusAttribute=['data-component','data-wire','data-terminal'].find(a=>active?.hasAttribute?.(a)),focusValue=focusAttribute?active.getAttribute(focusAttribute):null;const mount=$('#generator-mount'),viewport=$('#generator-viewport'),left=viewport.scrollLeft,top=viewport.scrollTop;mount.innerHTML=drawCircuit(circuit,{selection,filter,mode});navigation.apply();viewport.scrollLeft=left;viewport.scrollTop=top;if(focusAttribute)mount.querySelector(`[${focusAttribute}="${focusValue}"]`)?.focus({preventScroll:true});}
