function explain(){if(!circuit)return;const stages=stagesForCircuit(),stage=stages[step];selection={kind:'stage',ids:stage.ids};$('#explain-step').textContent=`${step+1} / ${stages.length} · ${stage.label}`;$('#explain-description').textContent=stage.description;$('#explain-back').disabled=step===0;$('#explain-next').disabled=step===stages.length-1;paint();}
