 const action=row=>{const button=el('button',row.fromLabel+' → '+row.toLabel);button.type='button';button.dataset.buildConnection=row.id;button.addEventListener('click',()=>inspect('wire',row.id));return button;};
 for(const [i,group] of guide.groups.entries()){const section=el('section');section.append(el('h3',String(i+1).padStart(2,'0')+' / '+group.label));for(const row of group.connections){const item=el('div');item.className='build-step';const label=el('label'),box=el('input');box.type='checkbox';box.setAttribute('aria-label','Mark connection complete: '+row.fromLabel+' to '+row.toLabel);box.addEventListener('change',()=>{if(box.checked)completed.add(row.id);else completed.delete(row.id);$('#build-progress').textContent=completed.size+' / '+guide.connections.length+' connections checked';});label.append(box,el('span','Done'));item.append(label,action(row),el('p',row.method+(row.shared.length?' Shared terminals: '+row.shared.map(ref=>terminalDescription(circuit,ref).label).join('; ')+'.':'')));section.append(item);}steps.append(section);}
 $('#build-progress').textContent='0 / '+guide.connections.length+' connections checked';
 for(const row of guide.connections){const tr=el('tr');tr.dataset.connection=row.id;const from=el('td');from.append(action(row));tr.append(from,el('td',row.purpose),Object.assign(el('td',row.kind),{className:'connection-diagnostic'}));rows.append(tr);}
 for(const part of guide.parts)parts.append(el('li',part.quantity+' × '+part.role+' · '+part.value+(part.existing?' · existing / not supplied':'')));
 $('#build-materials').textContent='Hookup conductors and any indicated ground/shield connections are required. Wire lengths and consumable quantities are not calculated. Verify terminal identity and continuity on the actual hardware before soldering.';
 const contacts=$('#build-contacts');contacts.replaceChildren();for(const pair of guide.contacts)contacts.append(el('li',pair.fromLabel+' ↔ '+pair.toLabel+' · closed at selector '+circuit.state.position));
