 form.elements.namedItem('bleed').disabled=state.wiring==='50s';$('#bleed-reason').hidden=state.wiring!=='50s';if(kitContext&&!kitCanRepresentCaps(state))kitContext=null;if(kitContext&&state.guitar==='les-paul'){kitContext=updateKitFromDiagram(kitContext,state);circuit=circuitForKit(kitContext,{colours:state.colours,position:state.position,shielding:state.shielding});circuit.state.pickupProfiles={...profiles};}else{kitContext=null;circuit=makeCircuit(state);}if(importedCircuit.state&&(state.guitar==='les-paul'||importedCircuit.state.version===2))applyCircuitAnalysis(circuit,importedCircuit.state);selection=null;completed.clear();renderWorkshop();clear();
