 $('#generator-import-note').textContent=importedSnapshot?'Circuit imported from Signal Forge. Pot values and independent pickup conductors are retained. Control positions and pickup/cable/input assumptions are retained for return to Signal Forge; the wiring drawing does not analyse their response.':'';
 $('#generator-shared-summary').textContent=importedSnapshot?circuitStateSummary(circuit):circuit.state.guitar.toUpperCase()+' · '+circuit.state.wiring+' wiring · selector '+circuit.state.position;$('#generator-source-circuit').hidden=!importedSnapshot;if(importedSnapshot)$('#generator-source-circuit').href=withProject(circuitStateURL('/circuit-forge/',importedSnapshot));
 const currentURL=new URL(generatorURL(state,kitContext,mode),window.location.origin);if(importedSnapshot)currentURL.searchParams.set('sf',JSON.stringify(importedSnapshot));history.replaceState(null,'',withProject(currentURL.pathname+currentURL.search));$('#installation-guide').href=withProject(installationGuideURL(state,kitContext));$('#installation-guide').hidden=state.guitar!=='les-paul';
 const plain=projectKitHandoff(circuit,projectContext),plainLink=plain.url,link=kitContext?builderDiagramURL(kitContext,state):plainLink?plainLink:null;$('#build-kit').hidden=!link;if(link)$('#build-kit').href=withProject(link);$('#kit-transfer-note').textContent=kitContext?'Your complete kit specification is retained. This is the full installation circuit. Return to the Builder and select Your Kit to highlight the parts Apparition supplies.':link&&plain.reason.startsWith('Previous')?plain.reason:link?'The circuit transfers with an Epiphone jack and Epiphone-style toggle selected. Review brands, shaft length, fitment and price in the builder.':'A matching kit product and fitment specification are not available for this layout yet. You can still inspect, export and print its wiring.';
 $('#generator-status').textContent=notice||(!colourCodes[state.colours].verified?'Colour code not yet verified. Generic conductors are shown; verify your exact pickup convention.':'Circuit generated. Select any component or connection to inspect it.');$('#export-svg').disabled=false;$('#print-diagram').disabled=false;
 const legend=$('#colour-legend');legend.replaceChildren(el('p','Wire colours indicate electrical roles unless a pickup manufacturer convention is explicitly selected. Dashed conductors identify shields; crossing hops do not join.'));for(const pickup of guide.pickups){legend.append(el('h3',pickup.label+' · '+pickup.profile.label));const list=el('ul');for(const lead of pickup.leads)list.append(el('li',lead.label));legend.append(list);}if(!guide.pickups.length)legend.append(el('p','Single-coil hot and ground are identified by function. Manufacturer colours are not assumed.'));
