form.addEventListener('submit',e=>e.preventDefault());form.addEventListener('change',e=>{if(e.target.name==='guitar'){projectContext=null;kitContext=null;importedCircuit={state:null,notice:''};setLayout(true);}if(e.target.name==='colours'){profiles={neck:e.target.value,bridge:e.target.value};syncProfiles();}if(['neckProfile','bridgeProfile'].includes(e.target.name)){profiles[e.target.name.startsWith('neck')?'neck':'bridge']=e.target.value;}if(importedCircuit.state?.configuration)importedCircuit.state.configuration.pickupProfiles={...profiles};render();});form.addEventListener('reset',()=>setTimeout(()=>{projectContext=null;kitContext=null;importedCircuit={state:null,notice:''};unavailableReason='';profiles={neck:'generic',bridge:'generic'};syncProfiles();setLayout(true);render();},0));
