$('#explain-panel').addEventListener('toggle',()=>{updateModeUI();if(mode==='explain'&&$('#explain-panel').open)explain();else if(selection?.kind==='stage')clear();});$('#explain-back').addEventListener('click',()=>{step=Math.max(0,step-1);explain();});$('#explain-next').addEventListener('click',()=>{step=Math.min(stagesForCircuit().length-1,step+1);explain();});
