let beforePrint;
window.addEventListener('beforeprint',()=>{if(!circuit)return;beforePrint={selection,filter,notes:[...document.querySelectorAll('.wiring-notes')].map(n=>[n,n.open])};for(const [node] of beforePrint.notes)node.open=true;$('#generator-mount').innerHTML=drawCircuit(circuit,{exporting:true,mode});$('#generator-mount').style.width='100%';});window.addEventListener('afterprint',()=>{if(beforePrint){({selection,filter}=beforePrint);for(const [node,open] of beforePrint.notes)node.open=open;beforePrint=null;paint();}});$('#print-diagram').addEventListener('click',()=>window.print());
function setLayout(reset){const guitar=form.elements.guitar.value,lp=['les-paul','sg'].includes(guitar),positions=form.elements.position,old=positions.value;positions.replaceChildren();for(const [v,label] of Object.entries(layoutInfo[guitar].positions)){const option=el('option',label);option.value=v;positions.append(option);}positions.value=!reset&&layoutInfo[guitar].positions[old]?old:lp?'both':'1';form.elements.wiring.disabled=!lp;form.elements.wiring.closest('label').hidden=!lp;if(!lp)form.elements.wiring.value='modern';$('#bridge-cap-control').hidden=!lp;form.elements.colours.disabled=['strat','tele'].includes(guitar);if(form.elements.colours.disabled)form.elements.colours.value='generic';if(reset){form.elements.neckCap.value=guitar==='prs'?'0.033':lp?'0.022':'0.047';form.elements.bridgeCap.value=form.elements.neckCap.value;form.elements.bleed.value=guitar==='prs'?'prs':'none';}$('#generator-pickup-profiles').hidden=['strat','tele'].includes(guitar);$('#layout-description').textContent=layoutInfo[guitar].description;form.querySelector('.eyebrow').textContent=layoutInfo[guitar].description;}
function syncProfiles(){for(const ch of ['neck','bridge'])form.elements.namedItem(ch+'Profile').value=profiles[ch];}
