const colourSelect=form.elements.colours;colourSelect.replaceChildren();for(const [id,entry] of Object.entries(pickupConventions)){const option=el('option',entry.label+(entry.verified?'':' · unverified'));option.value=id;colourSelect.append(option);}
let initialError='';try{const saved=readGeneratorURL(importedCircuit.notice&&!importedCircuit.state?'':location.search);requirePublicPlatform(saved.state);kitContext=saved.kit;profiles=saved.state.pickupProfiles||{neck:saved.state.colours,bridge:saved.state.colours};for(const [key,value] of Object.entries(saved.state))if(form.elements.namedItem(key))form.elements.namedItem(key).value=value;if(kitContext&&['premium','overkill'].includes(kitContext.bleed)){const option=el('option',kitContext.bleed==='premium'?'Premium Sprague Duncan-style · supplied kit':'Apparition Overkill-Pasitor · supplied kit');option.value=kitContext.bleed;form.elements.bleed.append(option);form.elements.bleed.value=kitContext.bleed;}}catch(e){initialError=e.message;try{const requested=JSON.parse(new URLSearchParams(location.search).get('g')||'{}');if(requested.guitar&&!['les-paul','sg','tele','strat'].includes(requested.guitar))unavailableReason='This platform is not yet modelled by the public Wiring Generator.';}catch{}}
